// Tarik laporan konversi Shopee (dijalankan HARIAN, jendela 7 hari untuk jaring pengaman
// kalau 1 hari gagal). Duplikat ditahan unique index (checkout_id, ts) di tabel conversions.
const crypto = require('crypto');
const appid = $env.SHOPEE_AFFILIATE_APPID;
const secret = $env.SHOPEE_AFFILIATE_SECRET;
if (!appid || !secret) throw new Error('SHOPEE_AFFILIATE_APPID/SECRET belum diisi');

const end = Math.floor(Date.now() / 1000);
const start = end - 7 * 24 * 3600;
const query = `{
  conversionReport(purchaseTimeStart: ${start}, purchaseTimeEnd: ${end}, scrollId: "", limit: 500, orderStatus: ALL) {
    nodes {
      checkoutId
      purchaseTime
      estimatedTotalCommission
      grossCommission
      cappedCommission
      totalBrandCommission
    }
    pageInfo { scrollId hasNextPage }
  }
}`;
const body = JSON.stringify({ query });
const ts = Math.floor(Date.now() / 1000);
const sign = crypto.createHash('sha256').update(appid + String(ts) + body + secret).digest('hex');
return {
  json: {
    body,
    auth: `SHA256 Credential=${appid}, Signature=${sign}, Timestamp=${ts}`,
    start,
    end
  }
};

// Agregat + simpan ke tabel conversions + siap ringkasan Telegram.
const rep = ($json.data && $json.data.conversionReport) || {};
const nodes = rep.nodes || [];
let total = 0;
const rows = [];
const esc = s => String(s ?? '').replace(/'/g, "''");
for (const n of nodes) {
  const comm = Number(n.estimatedTotalCommission || 0);
  total += comm;
  rows.push(`('${esc(n.checkoutId)}', ${comm}, to_timestamp(${Number(n.purchaseTime || 0)}), '${esc(JSON.stringify(n))}')`);
}
let sql = 'SELECT 1';
if (rows.length) {
  sql = `INSERT INTO conversions (checkout_id, commission, ts, raw) VALUES ${rows.join(',')} ON CONFLICT DO NOTHING;`;
}
const hasMore = !!(rep.pageInfo && rep.pageInfo.hasNextPage);
return {
  json: {
    sql,
    orders: nodes.length,
    total_commission: Math.round(total * 100) / 100,
    has_more: hasMore
  }
};

// Ringkasan mingguan dihitung dari DB (data sudah ditarik harian) — tidak tarik API dua kali.
return {
  json: {
    sql: "SELECT COALESCE(SUM(commission),0)::numeric(14,2) AS total, COUNT(*)::int AS orders FROM conversions WHERE ts >= now() - interval '7 days'"
  }
};

